def prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    if n < 0:
        return False

    D_n = D(n)

    if D_n == 0:
        # This shouldn't happen for non-negative n, but good practice.
        return False 

    # Check if D_n divides 20^(n+1)
    # 20^(n+1) = (2^2 * 5)^(n+1) = 2^(2n+2) * 5^(n+1)

    # Prime factorization of D_n
    factors = prime_factorization(D_n)

    # Check if all prime factors of D_n are 2 or 5
    for p in factors:
        if p not in [2, 5]:
            return False, factors # D_n has a prime factor other than 2 or 5

    # If all factors are 2 or 5, check the exponents
    # Required: exp_2(D_n) <= 2n+2 AND exp_5(D_n) <= n+1

    exp_2 = factors.get(2, 0)
    exp_5 = factors.get(5, 0)

    condition1 = exp_2 <= 2*n + 2
    condition2 = exp_5 <= n + 1

    return condition1 and condition2, factors

results = {}
for n in range(11):
    satisfied, factors = check_divisibility(n)
    D_n = D(n)
    results[n] = {
        'D(n)': D_n,
        'Satisfies': satisfied,
        'Factors': factors
    }

print("--- Results ---")
for n, data in results.items():
    print(f"n={n}: D(n)={data['D(n)']}, Satisfies={data['Satisfies']}, Prime Factors={data['Factors']}")

