def prime_factorization(k):
    factors = {}
    d = 2
    temp = k
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_m_squared_plus_1(m_limit=50):
    solutions = []
    for m in range(1, m_limit + 1):
        m_squared_plus_1 = m*m + 1
        factors = prime_factorization(m_squared_plus_1)

        # Check if all prime factors are 2 or 5
        is_valid = True
        for p in factors:
            if p != 2 and p != 5:
                is_valid = False
                break

        if is_valid:
            n = m - 1
            solutions.append((n, m_squared_plus_1))
            print(f"Found valid m={m} (n={n}): m^2+1 = {m_squared_plus_1}")
    return solutions

solutions = check_m_squared_plus_1(m_limit=50)
print(f"\nTotal solutions found up to m=50: {solutions}")

